import os, json, argparse
from pathlib import Path

def load_config():
    cfg = {'host':'localhost', 'port': 8080, 'debug': False}
    fp = Path.home() / '.config' / '{{app_name}}.json'
    if fp.exists():
        cfg.update(json.loads(fp.read_text()))
    for k in ('host','port','debug'):
        env = os.environ.get(f'{{app_name}}_{k}'.upper())
        if env is not None:
            cfg[k] = env
    ap = argparse.ArgumentParser()
    ap.add_argument('--host'); ap.add_argument('--port', type=int); ap.add_argument('--debug', action='store_true')
    args = ap.parse_args()
    for k, v in vars(args).items():
        if v not in (None, False): cfg[k] = v
    return cfg

print(load_config())
